<?php

declare(strict_types=1);

namespace Domain\Sharing\Api;

use App\Api\Contracts\Domains\ApiSender;
use App\Support\CallKey;
use Domain\Sharing\Data\ShareProposalStatusData;

/**
 * The API of Sharing, generated by php artisan journal:api; run it again instead of editing.
 */
final readonly class SharingApi
{
    public function __construct(private ApiSender $sender) {}

    public function requestShare(
        string $alias,
        string $number,
        CallKey $requestKey = new CallKey(),
    ): ShareProposalStatusData {
        return $this->sender->send(RequestSharePayload::from([
            'alias' => $alias,
            'number' => $number,
            'requestKey' => $requestKey,
        ]));
    }

    public function shareStatus(
    ): ShareProposals {
        return $this->sender->send(ShareStatusPayload::from([]));
    }
}
